    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        for name, value in params.items():
            sql = sql.replace(f'{{{{{name}}}}}', value)
        cursor.execute(sql)
        columns = [desc[0] for desc in cursor.description]
        rows = cursor.fetchall()
        return rows
    except Exception as e:
        return None
    finally:
        if conn:
            conn.close()

