import sqlite3
import json
import threading
import queue
import xml.etree.ElementTree as ET
from concurrent.futures import ThreadPoolExecutor, as_completed

def parse_xml(config_path):
    tree = ET.parse(config_path)
    root = tree.getroot()
    db_path = root.attrib['db']
    max_parallel = int(root.attrib['max_parallel'])
    queries = []
    for query_elem in root.findall('query'):
        queries.append({
            'id': query_elem.attrib['id'],
            'query': query_elem.text.strip()
        })
    return db_path, max_parallel, queries

def execute_query(db_conn, query_info):
    try:
        cursor = db_conn.cursor()
        cursor.execute(query_info['query'])
        row_count = cursor.rowcount
        return {'id': query_info['id'], 'row_count': row_count}
    except Exception as e:
        return {'id': query_info['id'], 'error': str(e)}

def process_queries(db_path, max_parallel, queries):
    conn = sqlite3.connect(db_path)
    query_queue = queue.Queue()
    results = []

    for query in queries:
        query_queue.put(query)

    with ThreadPoolExecutor(max_workers=max_parallel) as executor:
        futures = {executor.submit(execute_query, conn, query): query['id'] for query in query_queue}
        for future in as_completed(futures):
            result = future.result()
            results.append(result)

    conn.close()
    return results

def main():
    import sys
    if len(sys.argv) != 2:
        print("Usage: python run_queries.py config.xml", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    db_path, max_parallel, queries = parse_xml(config_path)
    results = process_queries(db_path, max_parallel, queries)

    for result in results:
        print(json.dumps(result))

if __name__ == "__main__":
    main()
